INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-mural-colectivo-scout', 'El Mural Colectivo Scout', 'Taller colaborativo de expresión plástica y diseño gráfico donde los scouts pintan un lienzo colectivo sobre vivencias scouts.', '<h2>📜 Descripción de El Mural Colectivo Scout</h2>
<p><b>El Mural Colectivo Scout</b> es un taller de expresión artística, diseño plástico colaborativo y pertenencia institucional. Sobre una tira continua de papel kraft o lienzo extendido en el suelo de campamento, cada patrulla recibe un sector asignado para plasmar una gran obra pictórica unificada (ej. <i>''La Historia y Leyenda Scout''</i>, <i>''El Cuidado de la Naturaleza en Rapa Nui''</i> o <i>''Nuestras Vivencias en la Selva''</i>). Utilizando pinturas, pinceles y lápices de colores, los equipos integran sus trazos individuales en una composición artística armónica.</p>
<p>Esta actividad ejercita el trabajo cooperativo, la creatividad visual y el sentido de identidad grupal en Manada, Compañía, Tropa, Avanzada y Clan.</p>

<h2>🎲 ¿Cómo se juega El Mural Colectivo Scout?</h2>
<p>Para llevar a cabo la dinámica con dinamismo y entusiasmo, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Preparación del Lienzo:</b> Se extiende el rollo de papel kraft o tela sobre mesas de trabajo o en el césped del campamento.</li>
  <li><b>Lluvia de Ideas y Boceto:</b> Las patrullas acuerdan los símbolos, paisajes e insignias scouts que incluirán en su sección.</li>
  <li><b>Pintura Colaborativa:</b> Los participantes pintan en paralelo respetando los empalmes y bordes con las patrullas vecinas.</li>
  <li><b>Detalles y Firmas:</b> Se agregan firmas de patrulla y la fecha del campamento con pinceladas finas.</li>
  <li><b>Exposición del Mural:</b> El lienzo completo se cuelga en el mástil o salón principal para el cierre de la jornada.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Mural Colectivo Scout</h2>
<p>La actividad valora la creatividad artística y el espíritu de equipo en el Tally:</p>
<ul>
  <li><b>Mayor Armonía Pictórica:</b> Otorgar 5 puntos al mural que integre los trazos de todas las patrullas con mayor fluidez.</li>
  <li><b>Riqueza de Simbolismo Scout:</b> Otorgar 3 puntos a la unidad que plasme la mística y los valores scouts con mayor profundidad.</li>
  <li><b>Limpieza y Colaboración:</b> Otorgar 3 puntos al equipo que cuide sus materiales y mantenga el orden del taller.</li>
</ul>', '/uploads/el-mural-colectivo-scout.webp', 'publicado', '{"areas": ["creatividad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Papel", "Lápices de Colores", "Pinceles"], "objetivos": ["Estimular la creatividad", "Trabajo en equipo", "Desarrollar la motricidad", "Crear un ambiente de distensión"], "justificacion_areas": "El Mural Colectivo Scout potencia la creatividad al requerir la traducción gráfica de valores e historias a una composición plástica de gran formato. Desarrolla la sociabilidad al afianzar la negociación de ideas, la división equitativa de tareas y el orgullo por la obra comunitaria desde Manada hasta Clan.", "variaciones": "<b>Mural de Manos e Insignias:</b> Imprimir huellas dactilares y siluetas de manos con pintura lavable.<br><b>Mural Ecológico de Materiales Reciclados:</b> Integrar hojas secas, cortezas y elementos naturales.<br><b>Mural Nocturno con Pintura Fluorescente:</b> Iluminar la obra con luz negra durante la velada de campamento.", "recomendaciones": "Mantener recipientes con agua y paños de limpieza cerca. Fomentar la inclusión de todos los beneficiarios sin importar su soltura con el dibujo.", "objetivos_educativos": [{"id": "14b82459-ac31-4496-a875-8e9bd5666030", "area": "Creatividad", "unidad": "Manada", "texto": "En las actividades que hago se nota lo que pienso y siento.", "como_se_cumple": "Expresando sentimientos y creatividad plástica en los trazos del mural."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando los espacios asignados y cuidando los materiales de pintura."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Improvisando diseños y mezclas de colores colectivas."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Colaborando armoniosamente con la seisena en el coloreado."}, {"id": "d581cfa7-db1f-4b08-b4d3-525b23e418ea", "area": "Creatividad", "unidad": "Compañía", "texto": "Participo con entusiasmo en las actividades artísticas de mi Compañía.", "como_se_cumple": "Liderando bocetos y pinceladas principales en la sección del lienzo."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Favoreciendo el trabajo limpio y la ayuda mutua en el taller."}, {"id": "f9cea3e0-24f4-43ab-9efb-1a4541a29943", "area": "Creatividad", "unidad": "Compañía", "texto": "Ayudo a preparar materiales para las representaciones artísticas.", "como_se_cumple": "Organizando pinturas y pinceles para el mural de patrulla."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Aceptando las sugerencias de diseño de las compañeras de equipo."}, {"id": "39eaf1aa-f703-4fd0-a4b3-b9756dc30539", "area": "Creatividad", "unidad": "Tropa", "texto": "Participo con entusiasmo en las actividades artísticas de mi Tropa.", "como_se_cumple": "Aportando creatividad plástica en las representaciones visuales de la Tropa."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Demostrando orden y respeto por el trabajo de las demás patrullas."}, {"id": "6e910d1c-7021-49a5-9ece-637f480a1ec7", "area": "Creatividad", "unidad": "Tropa", "texto": "Expreso por distintos medios mis intereses y aptitudes artísticas.", "como_se_cumple": "Diseñando composiciones gráficas complejas sobre la mística scout."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Fomentando la fraternidad y el aliento constante en la patrulla."}, {"id": "d252cb51-c224-4528-90b3-e0288aa343dd", "area": "Creatividad", "unidad": "Avanzada", "texto": "Comparto con los demás mis inquietudes, aspiraciones y creaciones artísticas.", "como_se_cumple": "Compartiendo con la Avanzada la visión artística y el mensaje social del mural."}, {"id": "3fd19eb4-737c-43c5-9ea8-5e5307ce0309", "area": "Sociabilidad", "unidad": "Avanzada", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Liderando proyectos artísticos con sentido comunitario en la Avanzada."}, {"id": "91e60eba-e267-4d1a-b27b-ef61a7b03b31", "area": "Creatividad", "unidad": "Clan", "texto": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "como_se_cumple": "Promoviendo la expresión artística colectiva y la fraternidad en el Clan Rover."}, {"id": "b5954f1c-4d0d-4bdb-97d8-821583beb77e", "area": "Sociabilidad", "unidad": "Clan", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Viviendo el servicio y la hermandad scout en obras públicas comunitarias."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

